from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[3]
P=ROOT/'lib/content/courses/authored/diversity-advanced'
# Each check tests transfer of a concept, separately from its lesson's worked scenario.
checks=[
[
('What would most strengthen an inquiry into possible aversive racism in a discretionary decision?', 'Compare how equivalent evidence and uncertainty were treated across relevant cases.', 'Use the decision maker’s stated commitment to fairness as the principal measure.', 'Treat any exercise of discretion as sufficient evidence of racial discrimination.', 'Comparable decision evidence tests whether the standard shifted. Neither an assurance of fairness nor discretion alone answers that question.', 'The framework directs attention to how decisions operate under ambiguity. It does not diagnose people from their values or make all discretion discriminatory.'),
('Two units have different exception rates. What is the most defensible initial interpretation?', 'The difference warrants examination of comparable cases, access to options, and reasons for exceptions.', 'The lower rate is necessarily fairer because it shows stronger consistency.', 'The higher rate is necessarily fairer because it shows greater flexibility.', 'A rate alone does not show whether exceptions were authorized, accessible, or applied consistently to relevant circumstances.', 'Both rigid refusal and inconsistent flexibility can create problems. Examine the route and evidence before treating a higher or lower number as the answer.'),
('Which design feature makes a scoring rubric more reviewable?', 'A description of the job-related evidence that supports each criterion and how uncertainty is handled.', 'A larger numerical scale that permits finer distinctions between overall impressions.', 'A final average that removes the need to explain disagreement among reviewers.', 'Reviewability comes from the relationship between evidence and judgment. More numbers or an average cannot supply missing reasons.', 'Precision in a score is different from clarity in the standard. Reviewers must be able to explain what the score represents and why relevant judgments differ.'),
('A pilot shows that a clarification rule was followed reliably. Which conclusion does that finding directly support?', 'The intended clarification process was implemented in the reviewed cases.', 'The rule caused all observed changes in selection outcomes.', 'The decision makers no longer hold implicit racial associations.', 'Process adherence is an implementation finding. Causal outcome claims and claims about private associations require different evidence.', 'Match the conclusion to the measure. A record of completed clarification steps does not establish changes in motives, associations, or every subsequent outcome.')
],
[
('Which statement best expresses an institutional-norm analysis?', 'An apparently ordinary expectation can distribute advantage through its history and consequences.', 'A racial identity reliably predicts which workplace expectations a person supports.', 'Any practice associated with a dominant group lacks a legitimate functional purpose.', 'The analysis concerns how standards operate. It allows individual variation and asks whether a particular requirement is justified.', 'Identity is not a substitute for examining the norm. Historical association warrants inquiry, but does not by itself settle whether a present requirement serves the work.'),
('The origin of a long-standing requirement cannot be established. What can a reviewer still evaluate?', 'Its current purpose, acceptable evidence, accessibility, and consistency of application.', 'Only whether the requirement has been used for a sufficiently long time.', 'Nothing until a documented historical intention is recovered.', 'An unknown origin should be acknowledged. Present-day justification and consequences remain open to evidence-based review.', 'Longevity does not establish usefulness, and missing historical evidence does not prevent examining current effects. Avoid inventing an origin to support a preferred conclusion.'),
('Why can the benefit of the doubt be considered an organizational resource?', 'It can affect who receives clarification, recovery opportunities, sponsorship, or continued consideration.', 'It guarantees a favorable final outcome whenever it is offered.', 'It is always inappropriate because fair decisions must exclude contextual judgment.', 'Credibility affects access to further opportunities even before a final decision. It should be examined through comparable circumstances rather than eliminated indiscriminately.', 'Trust and contextual judgment can be legitimate. The concern is whether comparable people receive different opportunities to explain, learn, or recover without defensible reasons.'),
('Which evaluation would best distinguish a renamed norm from a changed allocation practice?', 'Review who receives information, can participate, and receives support under the revised standard.', 'Count how often the new terminology appears in internal communications.', 'Ask only whether existing decision makers prefer the new label.', 'A changed allocation practice affects access and decisions. Vocabulary and preference can describe communication but do not establish those effects.', 'Look beyond the label to the route people actually use. Access and work quality should be examined together rather than inferred from more inclusive terminology.')
],
[
('What makes an analysis intersectional rather than simply a list of identities?', 'It explains how conditions and forms of power interact to produce a particular barrier.', 'It assigns a separate disadvantage value to each identity and adds the values.', 'It assumes everyone sharing the same combination of identities has the same experience.', 'Intersectional analysis explains a mechanism in context. It neither calculates identity totals nor treats group membership as a complete personal account.', 'Look for the relationship among rules, resources, and interpretations. Listing categories may identify questions, but it does not explain how the barrier occurred.'),
('A case supports two plausible explanations for a missed opportunity. What is the best next analytical step?', 'Identify information that would distinguish the explanations, including evidence against the favored one.', 'Select the explanation that contains the greatest number of identity categories.', 'Keep only examples consistent with the explanation that initially seemed most persuasive.', 'Testing alternatives makes the explanation more credible and helps identify the appropriate remedy.', 'A richer identity inventory or a collection of confirming examples does not replace testing the mechanism. A good analysis remains open to evidence that changes its conclusion.'),
('When might both a general improvement and a targeted repair be needed?', 'When a common design change removes one barrier but a distinct access need remains.', 'Whenever an employee belongs to more than one social category.', 'Only when the general improvement has already failed for every participant.', 'Remedies should match the actual interacting conditions. A broad improvement may be valuable while leaving a specific access barrier unresolved.', 'Identity count does not determine the remedy, and universal failure is not a prerequisite for a targeted response. Examine what each proposed component actually changes.'),
('Which case conclusion is most carefully bounded?', 'The documented combination restricted access in this case; broader prevalence remains unestablished.', 'The case establishes the same experience for everyone in the combined group.', 'The barrier is unimportant because a single case cannot establish population prevalence.', 'A specific finding can be meaningful and actionable without supporting a universal claim.', 'Avoid both overgeneralization and dismissal. The scope of the claim should match the evidence, while the identified barrier still receives an appropriate response.')
],
[
('Which credibility question is most directly about evidence rather than the speaker’s social standing?', 'What did the person observe, and what information could confirm or challenge the account?', 'Does the person hold a title that makes the account institutionally important?', 'Does the person use the vocabulary normally used by senior reviewers?', 'The first question examines the claim itself. Titles and vocabulary can influence impressions without establishing accuracy.', 'Fair inquiry does not require accepting every statement. It requires applying relevant evidence standards without substituting status or familiar style for examination.'),
('Why might an empty reporting category fail to show that no problem exists?', 'The available categories or reporting route may prevent the experience from being recorded.', 'Every absence of reports demonstrates that people are being deliberately silenced.', 'An open text box guarantees that all relevant experiences will reach decision makers.', 'Reporting arrangements shape what becomes visible. Their design and actual handling need review before drawing a conclusion from absence.', 'Neither silence nor a text box has one guaranteed meaning. Check whether people can describe the concern and whether someone is accountable for responding.'),
('What makes a consultation response record useful even when a suggestion is declined?', 'It shows the issue considered, evidence, decision, reason, and a way to correct a misrepresentation.', 'It demonstrates that participants agreed with the final decision.', 'It transfers final authority to everyone who submitted a comment.', 'A response record makes reasoning accountable without promising agreement or authority that participants do not hold.', 'Consultation, consent, and decision authority are different. A clear explanation can respect a contribution while accurately stating a constraint or disagreement.'),
('After improving a concern-reporting route, the number of reports rises. What can be concluded from that count alone?', 'The reporting volume increased; the cause still requires examination.', 'The underlying level of harmful conduct necessarily increased.', 'The revised process necessarily failed to improve access.', 'More reports can reflect access, trust, underlying conditions, or several factors. The count needs process evidence and appropriate feedback.', 'Do not treat reporting volume as self-explanatory. A better route can reveal concerns that were previously missing from the record.')
],
[
('What can a supervisor appropriately conclude from observing a colleague’s fatigue after repeated identity-related demands?', 'The recurring demands merit examination, while the colleague’s health condition remains unknown.', 'The colleague meets a clinical definition of racial battle fatigue.', 'No workplace action is possible without a medical explanation.', 'Observable organizational demands can be addressed without making a diagnosis or requiring disclosure.', 'Fatigue has many possible explanations. The research concept does not authorize clinical conclusions, and a preventable workplace burden can be corrected without a diagnosis.'),
('Which example describes explanatory work following an incident?', 'Having to repeatedly describe why the conduct mattered to several different reviewers.', 'Receiving an accessible copy of an already corrected document.', 'Choosing not to participate in an optional conversation.', 'Repeatedly explaining an incident is work that can accumulate. A coordinated response may reduce unnecessary repetition within appropriate information boundaries.', 'The burden map distinguishes practical, explanatory, and relationship-management tasks. It should help assign organizational responsibility rather than require more personal testimony.'),
('Which boundary best preserves an informed choice about seeking support?', 'Explain the role, available options, and relevant information-sharing limits before inviting sensitive details.', 'Promise that every conversation will remain completely confidential.', 'Refer the person elsewhere and treat the organizational conduct as resolved.', 'Clear boundaries let a person decide what to share and which route to use while the organization remains responsible for its own conduct.', 'Support requires accurate limits and follow-through. Neither unsupported secrecy nor referral alone resolves the workplace issue.'),
('Which finding would support a claim about reduced organizational burden rather than a private health outcome?', 'The revised handoff reduced the number of times a person had to repeat an account.', 'Fewer people volunteered personal stories in a team meeting.', 'A manager rated employees as more emotionally resilient.', 'The handoff measure directly concerns a process demand. It does not require an interpretation of private distress or recovery.', 'Silence and a manager’s impression cannot establish a health outcome. Review the conditions changed and keep personal emotional states outside informal personnel assessment.')
],
[
('Which distinction is essential when defining restorative success?', 'A concrete repair can occur without forgiveness or renewed closeness.', 'A sincere apology necessarily restores the previous relationship.', 'Declining reconciliation means that no practical repair is possible.', 'Repair, forgiveness, and reconciliation concern different choices and outcomes. The organization should not require one as proof of another.', 'A person may accept correction while remaining cautious or declining contact. Restoration must not make practical support conditional on an emotional or relational outcome.'),
('What does equal speaking time fail to establish by itself?', 'That participants can withdraw without employment pressure or other unequal consequences.', 'That the meeting has an agenda.', 'That both people have an opportunity to say at least one sentence.', 'Formal symmetry in the room does not remove outside authority over assignments, evaluation, or future opportunities.', 'Preparation must examine actual power and alternatives. A balanced meeting format is useful but cannot alone establish informed, voluntary participation.'),
('Which commitment is easiest to review for completion?', 'Correct the inaccurate attribution by an agreed date and identify who will communicate the correction.', 'Both participants will feel that the relationship has returned to normal.', 'Everyone will demonstrate a positive attitude about the process.', 'A concrete action has an owner, deadline, and observable result. Emotional and attitude demands are less reviewable and may create pressure.', 'Accountable repair connects an action to the consequence being addressed. Avoid making gratitude, forgiveness, or emotional agreement an institutional requirement.'),
('What is a legitimate reason to pause a restorative process?', 'A new concern that participation is being pressured or that information boundaries are unclear.', 'A participant remains unwilling to forgive after an agreed correction.', 'The organization wants a faster public statement that the matter is closed.', 'A pause can protect informed choice and process integrity. Appropriate formal and support routes should remain available.', 'Discomfort with an incomplete ending is not a reason to pressure closure. Evaluate safeguards and commitments rather than requiring a preferred emotional result.')
],
[
('Why must network composition be considered when interpreting homophily?', 'Similar connections can partly reflect who has an opportunity to meet, rather than preference alone.', 'A homogeneous work unit proves that all relationships within it are intentionally exclusionary.', 'Network patterns cannot affect access unless someone admits intending exclusion.', 'The available pool of contacts shapes patterns. Intent and consequences need separate evidence.', 'Homophily describes a pattern, not a motive. Examine opportunities for contact and the organizational consequences before drawing conclusions about individual choices.'),
('Which statement best captures the limit of a weak-ties finding from a professional-network platform?', 'It can inform questions about information pathways without guaranteeing internal workplace advancement effects.', 'It proves that every additional contact improves a person’s career prospects.', 'It shows that close supportive relationships are no longer useful.', 'A result belongs to its setting and design. Bridging information and close support can serve different useful functions.', 'Avoid turning a contextual research result into universal networking advice. Access also depends on time, support, authority, and the organization’s allocation rules.'),
('Which rule creates a circular barrier to a first developmental opportunity?', 'Only prior recipients of the same opportunity may be considered for it.', 'Applicants may demonstrate relevant capability through several forms of evidence.', 'An assignment requiring specialist knowledge has a clearly justified qualification.', 'A prior-opportunity-only rule can make experience unavailable to outsiders while using that absence to justify continued exclusion.', 'Distinguish a closed loop from a legitimate requirement. A supported entry route can widen access without abandoning the capabilities the task actually needs.'),
('Why should a review examine support and credit after selection?', 'Entry into an assignment does not establish that participants receive equally meaningful development.', 'A wider participant mix makes all later conditions irrelevant.', 'Only the final list of names determines whether an opportunity has value.', 'Preparation, resources, and recognition affect the quality of the opportunity after entry.', 'Selection is one stage of the route. Review whether people can succeed and receive appropriate credit rather than treating participation counts as the entire outcome.')
],
[
('A training changes an immediate implicit-association measure. Which additional claim remains unestablished?', 'That the change persists and improves the intended workplace behavior.', 'That the immediate measure differed under the study’s conditions.', 'That the study used a measure rather than only an attendance count.', 'Immediate measured change is distinct from durability and behavioral transfer; each needs relevant evidence.', 'Match claims to measures and follow-up. A short-term association result cannot automatically establish long-term changes in decisions or outcomes.'),
('A proposed evaluation would randomly withhold an access support. What should happen before proceeding?', 'Seek appropriate authority and research or ethics guidance; required access or protection must not be withheld for a test.', 'Proceed because random assignment always makes a design both ethical and rigorous.', 'Call it service improvement so that questions of authorization no longer apply.', 'The label does not settle responsibilities. The intervention’s consequences and applicable requirements determine what guidance and safeguards are needed.', 'A stronger causal design is not automatically permissible. Evaluation quality includes authority, ethics, and preservation of required services and protections.'),
('What is the purpose of a balancing measure?', 'To detect an important burden or unintended effect elsewhere in the process.', 'To average favorable and unfavorable results into one score that hides differences.', 'To replace the primary outcome when it does not improve.', 'A balancing measure keeps consequences such as delay or reduced access visible alongside the intended benefit.', 'Measures should answer distinct questions. Do not use a balancing indicator to conceal tradeoffs or change the definition of success after seeing the results.'),
('Which end-of-pilot decision is most consistent with disciplined learning?', 'Choose to continue, revise, stop, or evaluate further based on results, harms, and the limits of the comparison.', 'Expand any intervention that participants liked before checking its intended behavior.', 'Treat an inconclusive outcome estimate as proof that the original concern was imaginary.', 'A pilot can establish feasibility or expose a problem without proving every outcome. The next action should be proportionate to that evidence.', 'Neither enthusiasm nor uncertainty determines the answer alone. Examine implementation, alternatives, unintended effects, and what the design was capable of showing.')
],
[
('Which activity most clearly requires cooperation rather than simple proximity?', 'Participants use complementary knowledge to produce a shared result that none could complete as well alone.', 'Participants occupy the same room while completing unrelated individual tasks.', 'Two groups compete for a single recognition award without a shared task.', 'Cooperation involves a common goal and meaningful interdependence. Physical closeness alone does not create those conditions.', 'Contact quality depends on what people do together and under which conditions, not just whether different groups are present.'),
('Why can an apparently equal workshop still distribute burdens unequally?', 'Some participants may supply repeated identity explanations while others gain learning and retain decision authority.', 'Giving everyone the same number of minutes eliminates all relevant power differences.', 'Any difference in institutional role makes useful contact categorically impossible.', 'Look at explanatory work, benefits, and outside authority. A format can appear balanced while those conditions remain unequal.', 'Power differences require attention and safeguards; they are neither erased by equal time nor proof that every form of engagement must fail.'),
('What is the most appropriate use of perspective-taking in a cooperative task?', 'Use it to identify assumptions and questions that need checking with relevant people or evidence.', 'Treat imagined experience as an accurate account of what another group needs.', 'Ask one participant to confirm the imagined experience for an entire community.', 'Perspective-taking can generate useful questions, but it does not supply another person’s actual preferences or a representative account.', 'Imagination and individual testimony have limits. Preserve that distinction instead of converting either into authority to speak for a whole group.'),
('Which follow-up best tests whether a cooperative design task affected practice?', 'Review whether the shared product was used, what changed, and which concerns remain unresolved.', 'Use enjoyment ratings alone as evidence of lasting prejudice reduction.', 'Require participants to tell a positive story about the event.', 'Practice evidence concerns use and consequences of the work. Optional experience feedback answers a different question.', 'A pleasant encounter can be worthwhile without proving durable change. Preserve room for criticism and follow through on unresolved organizational responsibilities.')
],
[
('Which distinction prevents a legitimate limit from becoming moral exclusion?', 'A person can be ineligible for a service while remaining entitled to a fair, understandable process.', 'An unfavorable decision means the person no longer needs an explanation.', 'Respectful treatment requires approving every request regardless of authority.', 'Moral standing is not identical to eligibility. Boundaries can be maintained with accurate reasons, dignity, and appropriate next routes.', 'Neither denial of process nor unlimited approval follows from a legitimate constraint. Examine how the boundary is justified and how the person is treated.'),
('When does an administrative category become especially problematic?', 'When it replaces relevant individual information and justifies disregarding agency or context.', 'Whenever a case number is used for an authorized administrative purpose.', 'Only when the record includes an openly insulting word.', 'Categories can serve valid purposes, but should not become the complete account of a person or license indifference.', 'Look at how the category affects reasoning and treatment. Harmful reduction can occur without insults, while a relevant administrative identifier need not be dehumanizing.'),
('Which design principle makes fair treatment less dependent on sympathy?', 'Make appropriate information, choices, and review routes available without requiring a compelling personal story.', 'Give the most responsive service to people whose stories feel most familiar.', 'Require disclosure so staff can decide who is sufficiently deserving.', 'Human standing and usable procedures should not depend on emotional persuasion or willingness to disclose.', 'Empathy can help, but it cannot be the gatekeeper of fair process. Respect and relevant choices should remain available even without gratitude or a moving narrative.'),
('A team sees only its own handoff and not the consequences downstream. What is the most useful organizational response?', 'Trace the authorized process across handoffs and identify where explanation, agency, or correction becomes difficult.', 'Conclude that every staff member lacks empathy.', 'Improve the tone of local messages without examining the next steps.', 'A process view can reveal fragmented responsibility and burdens that an isolated team cannot see.', 'Do not substitute character judgments or wording changes for examining the route. Respectful practice depends on usable decisions and correction mechanisms as well as tone.')
]
]
assert len(checks)==10 and all(len(c)==4 for c in checks)
for course_index,f in enumerate(sorted(P.glob('div-*.ts'))):
 d=json.loads(f.read_text(encoding='utf-8').split('const pack: CoursePack = ',1)[1].split(';\n\nexport default',1)[0])
 for i,(lesson,row) in enumerate(zip(d['course']['lessons'],checks[course_index])):
  q,right,wrong1,wrong2,yes,no=row
  options=[{'text':right,'correct':True},{'text':wrong1,'correct':False},{'text':wrong2,'correct':False}]
  offset=(course_index+i)%3; options=options[offset:]+options[:offset]
  block=next(b for b in lesson['blocks'] if b['type']=='knowledgeCheck')
  block.update(question=q,options=options,feedbackCorrect=yes,feedbackIncorrect=no)
  assert not set(o['text'] for o in options)&set(o['label'] for o in lesson['scenario']['options'])
  if course_index==7 and i==1:
   lesson['learning']['objectives'][2]='Identify when a proposed evaluation needs appropriate research or ethics guidance.'
 f.write_text('import type { CoursePack } from "../../source-types";\n\nconst pack: CoursePack = '+json.dumps(d,ensure_ascii=False,indent=2)+';\n\nexport default pack;\n',encoding='utf-8')
print('Replaced 40 knowledge checks; 120 distinct answer options; no scenario-option duplicates. Narrowed intervention evaluation objective.')
